-- pg_get_partition_constraintdef and psql's `\d+` "Partition constraint"
-- line (generate_partition_qual), and check_new_partition_bound's overlap,
-- default-conflict, empty-range and hash-modulus errors with their cursor.
CREATE TABLE r (a int, b text) PARTITION BY RANGE (a);
CREATE TABLE r1 PARTITION OF r FOR VALUES FROM (1) TO (10);
CREATE TABLE r2 PARTITION OF r FOR VALUES FROM (MINVALUE) TO (-5);
CREATE TABLE rd PARTITION OF r DEFAULT;
CREATE TABLE r3 PARTITION OF r FOR VALUES FROM (20) TO (MAXVALUE) PARTITION BY LIST (b);
CREATE TABLE r3a PARTITION OF r3 FOR VALUES IN ('x', 'y', 'x');
CREATE TABLE r3b PARTITION OF r3 FOR VALUES IN (NULL);
CREATE TABLE r3c PARTITION OF r3 FOR VALUES IN (NULL, 'z');
CREATE TABLE r3d PARTITION OF r3 DEFAULT;
CREATE TABLE m (a int, b date, c bigint) PARTITION BY RANGE (a, b, c);
CREATE TABLE m1 PARTITION OF m FOR VALUES FROM (1, '2020-01-01', 5) TO (1, '2021-01-01', MINVALUE);
CREATE TABLE m2 PARTITION OF m FOR VALUES FROM (2, MINVALUE, MINVALUE) TO (3, MAXVALUE, MAXVALUE);
CREATE TABLE m3 PARTITION OF m FOR VALUES FROM (5, '2020-01-01', 1) TO (6, '2020-01-01', 1);
CREATE TABLE md PARTITION OF m DEFAULT;
CREATE TABLE l (v varchar(10), n numeric) PARTITION BY LIST (v);
CREATE TABLE l1 PARTITION OF l FOR VALUES IN ('a');
CREATE TABLE ld PARTITION OF l DEFAULT;
CREATE TABLE l2 (n numeric(10,2)) PARTITION BY LIST (n);
CREATE TABLE l21 PARTITION OF l2 FOR VALUES IN (1.5, -2, 3);
CREATE TABLE l2d PARTITION OF l2 DEFAULT;
CREATE TABLE t (v varchar(10), c char(3), x text COLLATE "C") PARTITION BY RANGE (v, c, x);
CREATE TABLE t1 PARTITION OF t FOR VALUES FROM ('a', 'x', 'it''s') TO ('b', 'y', 'q');
CREATE TABLE u (b bool) PARTITION BY LIST (b);
CREATE TABLE u1 PARTITION OF u FOR VALUES IN (true);
CREATE TABLE q ("A b" int8) PARTITION BY RANGE ("A b");
CREATE TABLE q1 PARTITION OF q FOR VALUES FROM (-3) TO (4);
CREATE TABLE rr (a int) PARTITION BY RANGE (a);
CREATE TABLE rrd PARTITION OF rr DEFAULT;
CREATE TABLE h (a int) PARTITION BY HASH (a);
CREATE TABLE h0 PARTITION OF h FOR VALUES WITH (REMAINDER 1, MODULUS 4);
SELECT c.relname,
       regexp_replace(pg_get_partition_constraintdef(c.oid), '''\d+''::oid', 'OID')
  FROM pg_class c
 WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p')
 ORDER BY 1;
SELECT pg_get_partition_constraintdef(0), pg_get_partition_constraintdef(NULL),
       pg_get_partition_constraintdef('r'::regclass);
\d+ r1
\d+ r3a
-- Overlaps report the new partition, the existing one PostgreSQL's bound
-- search finds and the written value it stopped at.
CREATE TABLE r1 PARTITION OF r FOR VALUES FROM (0) TO (1);
CREATE TABLE rx PARTITION OF r DEFAULT;
CREATE TABLE rx PARTITION OF r FOR VALUES FROM (5) TO (6);
CREATE TABLE rx PARTITION OF r FOR VALUES FROM (0) TO (2);
CREATE TABLE rx PARTITION OF r FOR VALUES FROM (12) TO (25);
CREATE TABLE rx PARTITION OF r FOR VALUES FROM (12) TO (10);
CREATE TABLE rx PARTITION OF r FOR VALUES FROM (MAXVALUE) TO (MAXVALUE);
CREATE TABLE mx PARTITION OF m FOR VALUES FROM (1, MAXVALUE, 1) TO (2, '2020-01-01', 1);
CREATE TABLE mx PARTITION OF m FOR VALUES FROM (1, '2020-06-01', 9) TO (1, '2020-07-01', 1);
CREATE TABLE mx PARTITION OF m FOR VALUES FROM (4, '2020-06-01', 9) TO (5, '2020-07-01', 1);
CREATE TABLE mx PARTITION OF m FOR VALUES FROM (0, '2020-06-01', 9) TO (1, '2020-07-01', 1);
CREATE TABLE mx PARTITION OF m FOR VALUES FROM (0, '2020-06-01') TO (1, '2020-07-01', 1);
CREATE TABLE mx PARTITION OF m FOR VALUES FROM (0, '2020-06-01', 1) TO (1, '2020-07-01');
CREATE TABLE lx PARTITION OF l FOR VALUES IN ('c', 'b', 'a');
CREATE TABLE r3x PARTITION OF r3 FOR VALUES IN ('w', NULL);
CREATE TABLE hx PARTITION OF h FOR VALUES WITH (MODULUS 3, REMAINDER 1);
CREATE TABLE hx PARTITION OF h FOR VALUES WITH (MODULUS 8, REMAINDER 5);
CREATE TABLE hx PARTITION OF h FOR VALUES WITH (MODULUS 2, REMAINDER 1);
CREATE TABLE hx PARTITION OF h FOR VALUES WITH (MODULUS 4, REMAINDER 4);
CREATE TABLE hx PARTITION OF h FOR VALUES WITH (MODULUS 0, REMAINDER 0);
CREATE TABLE hx PARTITION OF h FOR VALUES WITH (MODULUS 2, MODULUS 2);
CREATE TABLE hx PARTITION OF h FOR VALUES WITH (MODULUS 2, SIZE 2);
CREATE TABLE hx PARTITION OF h FOR VALUES WITH (MODULUS 2);
CREATE TABLE hx PARTITION OF h DEFAULT;
CREATE TABLE hx PARTITION OF h FOR VALUES IN (1);
CREATE TABLE lx PARTITION OF l FOR VALUES FROM (1) TO (2);
CREATE TABLE rx PARTITION OF r FOR VALUES WITH (MODULUS 2, REMAINDER 0);
CREATE TABLE IF NOT EXISTS r1 PARTITION OF r FOR VALUES FROM (0) TO (1);
CREATE TABLE ra (a int);
ALTER TABLE r ATTACH PARTITION ra FOR VALUES FROM (8) TO (12);
ALTER TABLE r ATTACH PARTITION ra DEFAULT;
-- ATTACH PARTITION checks the attached table's own columns, then the bound,
-- then the parent's columns.
CREATE TABLE ap (a int, b text NOT NULL) PARTITION BY LIST (a);
CREATE TABLE ap1 PARTITION OF ap FOR VALUES IN (1);
CREATE TABLE ac (a int);
ALTER TABLE ap ATTACH PARTITION ac FOR VALUES IN (1);
ALTER TABLE ap ATTACH PARTITION ac FOR VALUES IN (2);
CREATE TABLE ac2 (b text, a int, c int);
ALTER TABLE ap ATTACH PARTITION ac2 FOR VALUES IN (1);
CREATE TABLE ac3 (b int, a int);
ALTER TABLE ap ATTACH PARTITION ac3 FOR VALUES IN (2);
CREATE TABLE ac4 (b text COLLATE "C", a int);
ALTER TABLE ap ATTACH PARTITION ac4 FOR VALUES IN (2);
CREATE TABLE ac5 (b text, a int);
ALTER TABLE ap ATTACH PARTITION ac5 FOR VALUES IN (2);
CREATE TABLE ac6 (a int GENERATED ALWAYS AS IDENTITY, b text NOT NULL);
ALTER TABLE ap ATTACH PARTITION ac6 FOR VALUES IN (2);
CREATE TABLE ac7 (b text NOT NULL, a int);
ALTER TABLE ap ATTACH PARTITION ac7 FOR VALUES IN (2);
SELECT pg_get_partition_constraintdef('ac7'::regclass);
ALTER TABLE ac7 ATTACH PARTITION ap FOR VALUES IN (3);
CREATE TABLE ap3 (a int, b text NOT NULL) PARTITION BY LIST (a);
ALTER TABLE ap ATTACH PARTITION ap3 FOR VALUES IN (3);
ALTER TABLE ap3 ATTACH PARTITION ap FOR VALUES IN (3);
